"""Opt-in real Amazon contract test. Never reads configured personal source paths."""
import base64
from dataclasses import replace
import os
from pathlib import Path
import tempfile
import unittest

from amazon_sync_api.amazon import Amazon, Transport
from amazon_sync_api.core import Collection, digest, load_config, run

PNG = base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a0S8AAAAASUVORK5CYII=")


def fixture_settings(settings, base):
    """Use only generated bytes, regardless of the configured source paths."""
    if len(settings.collections) != 3:
        raise ValueError("Live fixture requires three collections")
    if any(not c.remote_root.startswith("integration-test-") for c in settings.collections):
        raise ValueError("Live fixture roots must start with integration-test-")
    collections = []
    for index, collection in enumerate(settings.collections):
        source = base / str(index)
        (source / "nested" / "empty").mkdir(parents=True)
        (source / "same.png").write_bytes(PNG)
        (source / "nested" / "same.png").write_bytes(PNG)
        collections.append(Collection(collection.id, source, collection.remote_root))
    return replace(settings, collections=tuple(collections), max_files=2, max_bytes=4096)


@unittest.skipUnless(os.environ.get("AMAZON_SYNC_LIVE") == "1", "Real Amazon test is opt-in")
class LiveAmazonTests(unittest.TestCase):
    def test_connect_create_tree_upload_retrieve_and_repeat(self):
        config = os.environ.get("AMAZON_SYNC_LIVE_CONFIG")
        self.assertTrue(config, "Set AMAZON_SYNC_LIVE_CONFIG to a private configuration")
        settings = load_config(config)
        with tempfile.TemporaryDirectory(prefix="amazon-synthetic-") as tmp:
            settings = fixture_settings(settings, Path(tmp))
            def fingerprint():
                return {(c.id, p.relative_to(c.source).as_posix()): digest(p)
                        for c in settings.collections for p in c.source.rglob("*.png")}
            before = fingerprint()
            provider = Amazon(Transport(settings.region, settings.cookies_file))
            first = run(settings, provider)
            self.assertEqual(sum(r["verified"] for r in first), 6)
            self.assertTrue(all(r["complete"] for r in first))
            # Check the cloud tree independently of the upload reports.
            for collection in settings.collections:
                root = provider.find(provider.root_id, collection.remote_root, "FOLDER")
                self.assertTrue(root)
                nested = provider.find(root, "nested", "FOLDER")
                self.assertTrue(nested)
                self.assertTrue(provider.find(nested, "empty", "FOLDER"))
                for parent in (root, nested):
                    node = provider.find_file(parent, "same.png")
                    self.assertTrue(node)
                    self.assertEqual(provider.original_sha256(node), next(iter(before.values())))
            second = run(settings, provider)
            self.assertEqual(sum(r["uploaded"] for r in second), 0)
            self.assertEqual(sum(r["already_verified"] for r in second), 6)
            self.assertEqual(before, fingerprint())


class FixtureGuardTests(unittest.TestCase):
    def test_configured_sources_are_replaced_with_generated_fixtures(self):
        from amazon_sync_api.core import Settings
        with tempfile.TemporaryDirectory() as tmp:
            base = Path(tmp)
            original = base / "do-not-read"
            settings = Settings("uk", "owner", base / "cookies", base / "state",
                tuple(Collection(n, original, "integration-test-" + n)
                      for n in ("immich", "captures", "photoscans")))
            generated = fixture_settings(settings, base / "generated")
            self.assertFalse(original.exists())
            self.assertEqual(sum(len(list(c.source.rglob("*.png")))
                                 for c in generated.collections), 6)
            with self.assertRaises(ValueError):
                fixture_settings(replace(settings, collections=(Collection("x", original, "immich"),)*3), base)
